import numpy as np

def demand(rep, lead_draws):
    lead = np.random.default_rng([rep, 1])
    lead.integers(1, 6, lead_draws)  # policies may use different numbers of lead times
    return np.random.default_rng([rep, 0]).poisson(5, 3).tolist()

